// Law: lawtwin.kafka::Broker: read-committed fetches never see open or aborted transactions
// [cluster]
// Description: While a transaction is open its records are past the last stable
// offset, which read-committed consumers do not pass. Once it aborts its
// records are skipped for ever. Read-uncommitted consumers see them both
// times.
// Rationale:
// References: KIP-98
// Expansion:
// Broker: read-committed fetches never see open or aborted transactions [cluster]
// for all (t :: Text) (txid :: Text) (batch :: List (lawtwin.kafka.model::type::Record)) . created
// (_input0) (1) implies transactionThenRead (_input0) (_input1) (_input2) (false) = true
fn law_12(
    ctx: &mut ls::Context,
    input_0: ls::Value,
    input_1: ls::Value,
    input_2: ls::Value,
) -> ls::Result<()> {
    let shared_cluster = std::sync::Arc::new(lawspec_abilities::lawtwin_kafka::Cluster::new(ctx));
    let installing = vec![
        ("lawtwin.kafka::ability::Broker".to_string(), ls::installed(shared_cluster.clone() as std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker>)),
    ];
    ctx.install_handlers(installing);
    let input_0 = lawspec_schema::schema()?.validate_with_context(
        input_0,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_1 = lawspec_schema::schema()?.validate_with_context(
        input_1,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_2 = lawspec_schema::schema()?.validate_with_context(
        input_2,
        &ls::TypeRef::named(
            "List",
            vec![ls::TypeRef::named(
                "lawtwin.kafka.model::type::Record",
                vec![],
            )],
        ),
        64,
        ctx,
    )?;
    {
        let condition = {
            let call_argument_0 = input_0.clone();
            let call_argument_1 = ls::Value::Integer(1i128.into());
            let arguments = vec![call_argument_0, call_argument_1];
            let result = lawspec_definitions::evaluate_79(ctx, arguments);
            let context = "lawtwin.kafka::created";
            result.map_err(|error| format!("{context}: {error}"))?
        };
        if condition.boolean()? {
            {
                let left = {
                    let call_argument_0 = input_0.clone();
                    let call_argument_1 = input_1.clone();
                    let call_argument_2 = input_2.clone();
                    let call_argument_3 = ls::Value::Bool(false);
                    let arguments = vec![
                        call_argument_0,
                        call_argument_1,
                        call_argument_2,
                        call_argument_3,
                    ];
                    let result = lawspec_definitions::evaluate_345(ctx, arguments);
                    let context = "lawtwin.kafka::transactionThenRead";
                    result.map_err(|error| format!("{context}: {error}"))?
                };
                let right = ls::Value::Bool(true);
                if !ls::equal(&left, &right)? {
                    return Err(format!(
                        "{}: {:?} != {:?}{}",
                        concat!(
                            "Broker: read-committed fetches never see open ",
                            "or aborted transactions [cluster] | expect tra",
                            "nsactionThenRead (_input0) (_input1) (_input2)",
                            " (false) = true",
                        ),
                        left,
                        right,
                        ls::difference(&left, &right),
                    ));
                }
            }
        }
    }
    Ok(())
}

