// Law: lawtwin.kafka::Broker: offsets sent in a transaction are committed only with it [cluster]
// Description:
// Rationale:
// References: KIP-98
// Expansion:
// Broker: offsets sent in a transaction are committed only with it [cluster]
// for all (t :: Text) (txid :: Text) (g :: Text) (offset :: Int64) . created (_input0) (1) implies
// transactionalOffsets (_input0) (_input1) (_input2) (_input3) = true
fn law_16(
    ctx: &mut ls::Context,
    input_0: ls::Value,
    input_1: ls::Value,
    input_2: ls::Value,
    input_3: ls::Value,
) -> ls::Result<()> {
    let shared_cluster = std::sync::Arc::new(lawspec_abilities::lawtwin_kafka::Cluster::new(ctx));
    let installing = vec![
        ("lawtwin.kafka::ability::Broker".to_string(), ls::installed(shared_cluster.clone() as std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka::Broker>)),
    ];
    ctx.install_handlers(installing);
    let input_0 = lawspec_schema::schema()?.validate_with_context(
        input_0,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_1 = lawspec_schema::schema()?.validate_with_context(
        input_1,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_2 = lawspec_schema::schema()?.validate_with_context(
        input_2,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_3 = lawspec_schema::schema()?.validate_with_context(
        input_3,
        &ls::TypeRef::named("Int64", vec![]),
        64,
        ctx,
    )?;
    {
        let condition = {
            let call_argument_0 = input_0.clone();
            let call_argument_1 = ls::Value::Integer(1i128.into());
            let arguments = vec![call_argument_0, call_argument_1];
            let result = lawspec_definitions::evaluate_79(ctx, arguments);
            let context = "lawtwin.kafka::created";
            result.map_err(|error| format!("{context}: {error}"))?
        };
        if condition.boolean()? {
            {
                let left = {
                    let call_argument_0 = input_0.clone();
                    let call_argument_1 = input_1.clone();
                    let call_argument_2 = input_2.clone();
                    let call_argument_3 = input_3.clone();
                    let arguments = vec![
                        call_argument_0,
                        call_argument_1,
                        call_argument_2,
                        call_argument_3,
                    ];
                    let result = lawspec_definitions::evaluate_346(ctx, arguments);
                    let context = "lawtwin.kafka::transactionalOffsets";
                    result.map_err(|error| format!("{context}: {error}"))?
                };
                let right = ls::Value::Bool(true);
                if !ls::equal(&left, &right)? {
                    return Err(format!(
                        "{}: {:?} != {:?}{}",
                        concat!(
                            "Broker: offsets sent in a transaction are comm",
                            "itted only with it [cluster] | expect transact",
                            "ionalOffsets (_input0) (_input1) (_input2) (_i",
                            "nput3) = true",
                        ),
                        left,
                        right,
                        ls::difference(&left, &right),
                    ));
                }
            }
        }
    }
    Ok(())
}

fn valid_16(
    ctx: &mut ls::Context,
    input_0: ls::Value,
    input_1: ls::Value,
    input_2: ls::Value,
    input_3: ls::Value,
) -> ls::Result<bool> {
    {
        let condition = {
            let call_argument_0 = input_0.clone();
            let arguments = vec![call_argument_0];
            let result = lawspec_definitions::evaluate_313(ctx, arguments);
            let context = "lawtwin.kafka::lawtwinKafkaModelValidTopicName";
            result.map_err(|error| format!("{context}: {error}"))?
        };
        if !condition.boolean()? {
            return Ok(false);
        }
    }
    {
        let condition = {
            let left = input_1.clone();
            let right = ls::Value::Text("".to_owned());
            ls::binary("!=", "Text", left, right)?
        };
        if !condition.boolean()? {
            return Ok(false);
        }
    }
    {
        let condition = {
            let left = input_2.clone();
            let right = ls::Value::Text("".to_owned());
            ls::binary("!=", "Text", left, right)?
        };
        if !condition.boolean()? {
            return Ok(false);
        }
    }
    {
        let condition = {
            let left = input_3.clone();
            let right = ls::Value::Integer(0i128.into());
            ls::binary(">=", "Integer", left, right)?
        };
        if !condition.boolean()? {
            return Ok(false);
        }
    }
    Ok(true)
}

